
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_optx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_optx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.396998818410679e+00, -4.309638203665798e+00, -4.187335980295797e+00, -4.018163739354218e+00, -3.788209377662407e+00, -3.483499964074574e+00, -3.094659016038839e+00, -2.626029830126539e+00, -2.109984767489460e+00, -1.610218087334301e+00, -1.120559833210730e+00, -7.247009489191740e-01, -6.209042910925812e-01, -5.044327256833980e-01, -3.686959871009599e-01, -2.574254866981440e-01, -1.686466149723126e-01, -6.981862072365501e-02, -1.550956692956408e-02, -1.746141573028510e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


